// Descobre dinamicamente as sessoes dos webinars perpetuos direto da API do ClickMeeting,
// SEM lista fixa de recurring_config_id. Assim a planilha acompanha sozinha quando o
// marketing troca ou adiciona webinars — nao precisa mais editar este codigo.
//
// Inclui: conferencia recorrente (recurring_config_id != null) do tipo webinar.
// Exclui: reunioes avulsas (sem serie) e series de teste (nome comeca com "test"/"teste"
//         ou id listado em BLOQUEIO_RID).
const BLOQUEIO_NOME = /\btest/i;           // pega "teste", "teste1", "test", "testing"...
const BLOQUEIO_RID = new Set(['17643']);   // series de teste conhecidas (ex.: "teste1")

// Junta as conferencias das duas chamadas (ativas + inativas).
// Tolera resposta ja dividida em itens, array bruto num item, ou {data:[...]}.
const confs = [];
for (const item of $input.all()) {
  const j = item.json;
  if (Array.isArray(j)) confs.push(...j);
  else if (j && Array.isArray(j.data)) confs.push(...j.data);
  else if (j && (j.id || j.recurring_config_id)) confs.push(j);
}

const out = [];
const ignorados = new Set();
for (const c of confs) {
  const rid = c.recurring_config_id;
  if (rid == null) continue;                                   // reuniao avulsa, sem serie
  const ridStr = String(rid);
  const nome = String(c.name || '').trim();
  if (c.room_type && c.room_type !== 'webinar') { ignorados.add(nome + ' (' + ridStr + ': nao-webinar)'); continue; }
  if (BLOQUEIO_RID.has(ridStr) || BLOQUEIO_NOME.test(nome)) { ignorados.add(nome + ' (' + ridStr + ': teste/bloqueado)'); continue; }
  out.push({ json: { sessionId: c.id, recurringConfigId: ridStr, marca: nome || ('Serie ' + ridStr) } });
}
if (ignorados.size) console.log('Series ignoradas: ' + Array.from(ignorados).join(' | '));
if (out.length === 0) console.log('Nenhuma sessao de webinar encontrada.');
return out;

// Deriva a serie/marca de cada inscrito pelo room_pin do PROPRIO link de acesso,
// cruzando com as conferencias (ativas + inativas). Sem lista fixa de series:
// o rotulo "Marca/Sala" e o proprio nome do webinar no ClickMeeting.
// Robusto — NAO depende de pairedItem (instavel apos o split do array do HTTP).

// Mapa room_pin -> { rid, nome }, montado a partir das conferencias.
// (o room_pin e constante por serie, entao resolve qualquer ocorrencia)
const pinInfo = {};
for (const nodeName of ['CM: conferências ativas', 'CM: conferências inativas']) {
  let items = [];
  try { items = $(nodeName).all(); } catch (e) { items = []; }
  for (const it of items) {
    const arr = Array.isArray(it.json) ? it.json : [it.json];
    for (const c of arr) {
      if (c && c.room_pin != null) {
        pinInfo[String(c.room_pin)] = {
          rid: String(c.recurring_config_id == null ? '' : c.recurring_config_id),
          nome: String(c.name || '').trim(),
        };
      }
    }
  }
}

function infoFromUrl(url) {
  const m = String(url || '').match(/clickmeeting\.com\/(\d+)/);
  return (m && pinInfo[m[1]]) ? pinInfo[m[1]] : { rid: '', nome: '' };
}

const rows = [];
for (const item of $input.all()) {
  const j = item.json || {};
  let recs = [];
  if (Array.isArray(j)) recs = j;
  else if (Array.isArray(j.body)) recs = j.body;
  else if (j.email || j.visitor_nickname || j.id) recs = [j];

  for (const r of recs) {
    const f = (r && r.fields) || {};
    const geo = (r && r.geo) || {};
    const email = (r.email || f['Email Address'] || '').toString().toLowerCase();
    if (!email) continue;
    const info = infoFromUrl(r.url);
    rows.push({ json: {
      'Data inscrição': r.registration_date || r.registration_confirmed || '',
      'Nome': r.visitor_nickname || f['Name'] || '',
      'Email': email,
      'Empresa': f['Company'] || '',
      'País': geo.country || '',
      'Cidade': geo.city || '',
      'Marca/Sala': info.nome || '(desconhecida)',
      'Série': info.rid,
      'Sessão': r.session_id || '',
      'Origem': r.http_referer || '',
      'Link de acesso': r.url || ''
    }});
  }
}
return rows;
